public class Main {
    public static String check(int n) {
        if (n > 0) {
            return "还有鱼干喵";
        }
        System.out.println("这句只在没战利品可叼的时候才轮到");
        return "碗空了喵";
    }

    public static void main(String[] args) {
        System.out.println(check(5));
        System.out.println(check(0));
    }
}

